def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_def = sum(1 for x in opp if x == 'D')
    my_def = sum(1 for x in my if x == 'D')

    if n == 1:
        return 'D'

    if n == 2:
        if opp_def == 0:
            return 'C'
        else:
            if opp[-1] == 'D' and opp[-2] == 'D':
                return 'D'
            return 'C'

    if opp_def == 0:
        return 'D'

    if opp_def > n * 0.6:
        return 'D'

    if opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'

    return 'C'
